window.app = {
    showToast(msg, icon='fa-bell'){ let c=document.getElementById('toast-container'); let t=document.createElement('div'); t.className='toast'; t.innerHTML=`<i class="fas ${icon} toast-icon"></i><span>${msg}</span>`; c.appendChild(t); setTimeout(()=>t.remove(),4000); },
    popup(msg,type='alert',cb=null){ let p=document.getElementById('custom-popup'); let acts=document.getElementById('popup-acts'); document.getElementById('popup-msg').innerText=msg; acts.innerHTML=''; if(type==='confirm'){ let no=document.createElement('button'); no.className='popup-btn btn-cancel'; no.innerText='No'; no.onclick=()=>p.style.display='none'; let yes=document.createElement('button'); yes.className='popup-btn btn-danger'; yes.innerText='Yes'; yes.onclick=()=>{ p.style.display='none'; if(cb) cb(); }; acts.append(no,yes); } else { let ok=document.createElement('button'); ok.className='popup-btn btn-confirm'; ok.innerText='OK'; ok.onclick=()=>p.style.display='none'; acts.appendChild(ok); } p.style.display='flex'; },
    async requestPushPermission(username){ try{ if('serviceWorker' in navigator){ const reg=await navigator.serviceWorker.register('./firebase-messaging-sw.js'); const perm=await Notification.requestPermission(); if(perm==='granted'){ const token=await getToken(messaging,{serviceWorkerRegistration:reg, vapidKey:'YOUR_VAPID_KEY_HERE'}); if(token) await setDoc(doc(db,"push_tokens",username),{token,lastUpdated:Date.now()},{merge:true}); } } } catch(e){ console.warn(e); } },
    async login(){ let u=document.getElementById('u-in').value.trim(); let p=document.getElementById('p-in').value.trim(); let err=document.getElementById('err-msg'); err.style.display='none'; if(u==='admin' && p==='admin@157390'){ this.finishLogin(u,true,false,false); return; } let found=USERS.find(n=>n.toLowerCase()===u.toLowerCase()); if(!found){ err.innerText="User not found"; err.style.display="block"; return; } let userRef=doc(db,"users",found); let snap=await getDoc(userRef); let valid=false; if(snap.exists()){ if(snap.data().password===p) valid=true; } else { if(p==="1234"){ await setDoc(userRef,{password:"1234"}); valid=true; } } if(valid){ let isOwner=(found==='Kartik'); let isAdmin= (found==='admin') || (snap.exists() && snap.data().role==='admin') || (found==='Kartik'); let isViceAdmin=snap.exists() && snap.data().role==='viceadmin'; this.finishLogin(found,isAdmin,isOwner,isViceAdmin); } else { err.innerText="Wrong Password"; err.style.display="block"; } },
    finishLogin(user,isAdmin,isOwner,isViceAdmin){ state.user=user; state.isAdmin=isAdmin; state.isOwner=isOwner; state.isViceAdmin=isViceAdmin; this.requestPushPermission(user); document.getElementById('loader-overlay').style.display='flex'; setTimeout(()=>{ document.getElementById('login-screen').style.display='none'; document.getElementById('main-app').style.display='block'; document.getElementById('loader-overlay').style.display='none'; if(isAdmin || isOwner || isViceAdmin) document.getElementById('admin-zone').style.display='block'; document.getElementById('u-name').innerText=user; document.querySelector('#u-role').innerText=isOwner?"Owner":(isAdmin?"Administrator":(isViceAdmin?"Vice Admin":"Student")); document.getElementById('u-img').src=`https://ui-avatars.com/api/?name=${user}&background=random`; this.listen(); },1000); },
    logout(){ location.reload(); },
    toggleNotificationDrawer(){ let d=document.getElementById('notif-drawer'); d.classList.toggle('open'); if(d.classList.contains('open')){ this.markNotificationsRead(); } },
    markNotificationsRead(){ state.notifUnread=0; document.getElementById('notif-badge').classList.add('hidden'); },
    addNotification(msg,type='info'){ let n={id:Date.now(),msg,type,time:Date.now(),read:false}; state.notifications.unshift(n); state.notifUnread++; let badge=document.getElementById('notif-badge'); if(badge){ badge.innerText=state.notifUnread; badge.classList.remove('hidden'); } this.renderNotificationDrawer(); },
    renderNotificationDrawer(){ let container=document.getElementById('notif-list'); if(!container) return; container.innerHTML=''; state.notifications.slice(0,30).forEach(n=>{ let div=document.createElement('div'); div.className='list-card'; div.style.padding='12px'; div.innerHTML=`<div><small>${new Date(n.time).toLocaleString()}</small><p>${n.msg}</p></div>`; container.appendChild(div); }); },
    async listen(){
        onSnapshot(collection(db,"profiles"),(s)=>{ s.forEach(d=>{state.profiles[d.id]=d.data().img;}); if(state.profiles[state.user]) document.getElementById('u-img').src=state.profiles[state.user]; document.querySelectorAll('.skeleton').forEach(el=>el.classList.remove('skeleton')); });
        onSnapshot(doc(db,"settings","holidays"),(s)=>{ state.holidays=s.exists()?s.data():{}; this.renderCal(); });
        onSnapshot(doc(db,"settings","structure"),(s)=>{ state.structure=s.exists()?s.data():{notes:{},papers:{}}; if(['notes','papers'].includes(state.modalType) && !state.currentSubject) this.open(state.modalType); });
        onSnapshot(doc(db,"settings","banned"),(s)=>{ if(s.exists()){ let d=s.data(); state.banned=d.list||[]; state.vips=d.vips||[]; if(state.banned.includes(state.user) && !state.isAdmin && !state.isOwner) { document.getElementById('ban-screen').style.display='flex'; document.getElementById('main-app').style.display='none'; } } });
        onSnapshot(doc(db,"settings","chat"),(s)=>{ state.chatMuted=s.exists()?s.data().muted:false; let btn=document.querySelector('#admin-mute-btn span'); if(btn) btn.innerText=state.chatMuted?"Unmute Global Chat":"Mute Global Chat"; if(state.modalType==='chat') this.renderChatUI(); });
        onSnapshot(doc(db,"settings","typing"),(s)=>{ let tw=document.getElementById('typing-wrap'); if(s.exists() && tw && state.modalType==='chat'){ let users=(s.data().users||[]).filter(u=>u!==state.user); if(users.length){ tw.style.display='flex'; document.getElementById('typing-text').innerText=`${users.join(',')} typing...`; } else tw.style.display='none'; } });
        onSnapshot(query(collection(db,"chats"),orderBy("time","asc")),(s)=>{ state.chats=[]; s.forEach(d=>{ let msg={id:d.id,...d.data()}; if(!msg.deletedBy||!msg.deletedBy.includes(state.user)) state.chats.push(msg); if(state.modalType==='chat' && msg.user!==state.user && (!msg.seenBy||!msg.seenBy.includes(state.user))) updateDoc(doc(db,"chats",msg.id),{seenBy:arrayUnion(state.user)}).catch(()=>{}); }); if(document.getElementById('chat-feed') && state.modalType==='chat') this.renderChat(); });
        onSnapshot(query(collection(db,"secret_chats"),orderBy("time","asc")),(s)=>{ state.secretChats=[]; s.forEach(d=>state.secretChats.push({id:d.id,...d.data()})); if(state.modalType==='ask-secret') this.renderSecretChat(); });
        onSnapshot(query(collection(db,"report_complaints"),orderBy("time","asc")),(s)=>{ state.reportComplaints=[]; s.forEach(d=>state.reportComplaints.push({id:d.id,...d.data()})); if(state.modalType==='report-complaint') this.renderReportChat(); });
        onSnapshot(query(collection(db,"messages"),orderBy("time","asc")),(s)=>{ state.messages=[]; let uc=0; s.forEach(d=>{ let msg={id:d.id,...d.data()}; state.messages.push(msg); if(msg.receiver===state.user && !msg.seen) uc++; }); let badge=document.getElementById('badge-msg'); if(badge){ if(uc>0){ badge.innerText=uc; badge.classList.remove('hidden'); } else badge.classList.add('hidden'); } if(state.modalType==='messages') state.activeMsgUser?this.renderDirectMessages():this.renderMessagesMenu(); });
        onSnapshot(query(collection(db,"homework"),orderBy("time","desc")),(s)=>{ state.homework=[]; s.forEach(d=>state.homework.push({id:d.id,...d.data()})); if(state.modalType==='homework') this.renderHomework(); });
        onSnapshot(query(collection(db,"school_work"),orderBy("time","desc")),(s)=>{ state.schoolWork=[]; s.forEach(d=>state.schoolWork.push({id:d.id,...d.data()})); if(state.modalType==='school-work') this.renderSchoolWork(); });
        onSnapshot(collection(db,"announcements"),(s)=>{ state.anns=[]; s.forEach(d=>state.anns.push({id:d.id,...d.data()})); if(document.getElementById('ann-feed')) this.renderAnn(); });
        onSnapshot(collection(db,"attendance_log"),(s)=>{ state.attn={}; s.forEach(d=>{state.attn[d.id]=d.data();}); let statusEl=document.getElementById('my-att-status'); let today=getLocalDate(); if(statusEl && state.attn[today] && state.attn[today][state.user]) statusEl.innerHTML=`Status: <b style="color:${state.attn[today][state.user]==='P'?'#10b981':'#ef4444'}">${state.attn[today][state.user]}</b>`; this.renderCal(); if(state.modalType==='attendance') this.renderAttendanceDash(document.getElementById('f-body')); });
        onSnapshot(doc(db,"settings","exam"),(s)=>{ state.exam=s.exists()?s.data():null; this.renderScheduleBoard(); });
        onSnapshot(collection(db,"events"),(s)=>{ state.events=[]; s.forEach(d=>state.events.push({id:d.id,...d.data()})); this.renderCal(); this.renderScheduleBoard(); });
        onSnapshot(doc(db,"settings","timetable"),(s)=>{ let data=s.exists()?s.data():{rows:["08:00","09:00"],data:{}}; state.tt['10thA']=data['10thA']||{rows:data.rows||["08:00","09:00"],data:data.data||{}}; state.tt['10thB']=data['10thB']||{rows:["08:00","09:00"],data:{}}; state.tt.active=state.tt.active||'10thA'; if(document.getElementById('tt-grid')) this.renderTimeTable(); });
        onSnapshot(collection(db,"teachers"),(s)=>{ state.teachers=[]; s.forEach(d=>state.teachers.push({id:d.id,...d.data()})); if(document.getElementById('teach-list')) this.renderTeachers(); });
        onSnapshot(collection(db,"resources"),(s)=>{ state.resources=[]; s.forEach(d=>state.resources.push({id:d.id,...d.data()})); if(state.currentChapter) this.openChapter(state.modalType,state.currentSubject,state.currentChapter); });
    },
    uploadAvatar(){ document.getElementById('avatar-input').click(); },
    handleModalBack(){ if(state.modalType==='homework-detail') this.open('homework'); else if(state.modalType==='messages' && state.activeMsgUser){ state.activeMsgUser=null; this.open('messages'); } else if(state.modalType==='ask-secret') this.openSecretProgress(); else if(state.currentChapter){ state.currentChapter=null; this.openSubject(state.modalType,state.currentSubject); } else if(state.currentSubject){ state.currentSubject=null; this.open(state.modalType); } else { document.getElementById('feature-modal').style.display='none'; this.closeMedia(); } },
    open(t){ state.modalType=t; state.currentSubject=null; state.currentChapter=null; let m=document.getElementById('feature-modal'); m.style.display='flex'; document.getElementById('f-title').innerText=t.toUpperCase().replace('-',' '); document.getElementById('f-subtitle').innerText=""; let b=document.getElementById('f-body'); b.innerHTML=''; if(['notes','papers'].includes(t)){ let html='<div class="folder-grid" style="padding:20px;">'; if(state.isAdmin||state.isOwner||state.roles[t+'Incharge']) html+=`<div class="folder-card" style="border-color:var(--success); border-style:dashed;" onclick="app.modal('New Folder',[{id:'f',label:'Folder Name'}],v=>app.addFolder('${t}',v[0]))"><i class="fas fa-plus folder-icon" style="color:var(--success)"></i><span class="folder-name">Create Folder</span></div>`; Object.keys(state.structure[t]||{}).forEach(f=>{ html+=`<div class="folder-card" onclick="app.openSubject('${t}','${f}')"><i class="fas fa-folder folder-icon"></i><span class="folder-name">${f}</span>${(state.isAdmin||state.isOwner||state.roles[t+'Incharge'])?`<i class="fas fa-trash" style="margin-top:10px; color:var(--danger);" onclick="event.stopPropagation(); app.delFolder('${t}','${f}')"></i>`:''}</div>`; }); b.innerHTML=html+'</div>'; } else if(t==='homework') this.renderHomework(); else if(t==='school-work') this.renderSchoolWork(); else if(t==='messages') this.renderMessagesMenu(); else if(t==='chat'){ b.innerHTML=`<div class="chat-wrap"><div id="chat-feed" class="chat-feed"></div><div id="typing-wrap" class="typing-wrap" style="display:none;"><div class="typing-indicator"><span></span><span></span><span></span></div><span id="typing-text"></span></div><div id="reply-bar" class="reply-preview" style="display:none"><span>Replying...</span><i class="fas fa-times" onclick="app.cancelReply()"></i></div><div id="chat-bar-container"></div></div>`; this.renderChatUI(); this.renderChat(); } else if(t==='report-complaint') this.renderReportChatUI(b); else if(t==='ask-secret') this.openSecretProgress(); else if(t==='progress') this.renderProgressDashboard(); else if(t==='timetable'){ b.innerHTML=`<div class="dual-tt-selector"><div class="tt-option ${state.dualTT==='10thA'?'active':''}" onclick="app.switchTimetable('10thA')">10th A</div><div class="tt-option ${state.dualTT==='10thB'?'active':''}" onclick="app.switchTimetable('10thB')">10th B</div></div><div class="tt-wrapper"><div class="tt-grid" id="tt-grid"></div></div>`; if(state.isAdmin||state.isOwner||state.roles.timetableIncharge) b.innerHTML+=`<div style="display:flex;gap:10px;margin:20px;"><button class="btn" style="flex:1;background:#333;" onclick="app.modal('Add Row',[{id:'t',label:'Time'}],v=>app.addTTRow(v[0]))">+ Row</button><button class="btn" style="flex:2;background:var(--primary);" onclick="app.saveTT()">Save Changes</button></div>`; this.renderTimeTable(); } else if(t==='teach'){ b.innerHTML='<div style="padding:20px;"></div>'; let c=b.firstChild; if(state.isOwner) c.innerHTML=`<button class="btn" style="width:100%;background:var(--primary);margin-bottom:15px;" onclick="app.addTeacherWithImage()">Add Teacher</button>`; c.innerHTML+=`<div id="teach-list"></div>`; this.renderTeachers(); } else if(t==='attendance') this.renderAttendanceDash(b); else if(t==='ann'){ b.innerHTML='<div style="padding:20px;"></div>'; let c=b.firstChild; if(state.isAdmin||state.isOwner||state.roles.announcementIncharge) c.innerHTML=`<div style="background:var(--surface);padding:15px;border-radius:16px;margin-bottom:15px"><textarea id="a-in" style="width:100%;background:transparent;border:none;color:white;outline:none;min-height:60px" placeholder="Write Announcement..."></textarea><div style="display:flex;justify-content:space-between;margin-top:10px"><label style="color:var(--accent)"><i class="fas fa-paperclip"></i><input type="file" hidden multiple onchange="app.handleAnnFile(event)"></label><button class="btn" style="background:var(--primary);padding:8px 20px;" onclick="app.postAnn()">Post</button></div></div>`; c.innerHTML+=`<div id="ann-feed"></div>`; this.renderAnn(); } },
    switchTimetable(ver){ state.dualTT=ver; state.tt.active=ver; this.renderTimeTable(); },
    renderTimeTable(){ let g=document.getElementById('tt-grid'); if(!g) return; let current=state.tt[state.dualTT]; if(!current) current={rows:["08:00","09:00"],data:{}}; g.innerHTML=`<div class="tt-cell tt-head">Time</div>`+["Mon","Tue","Wed","Thu","Fri","Sat"].map(d=>`<div class="tt-cell tt-head">${d}</div>`).join(''); current.rows.forEach((t,i)=>{ g.innerHTML+=`<div class="tt-cell tt-time">${t} ${(state.isAdmin||state.isOwner||state.roles.timetableIncharge)?`<i class="fas fa-trash" style="margin-left:8px; color:var(--danger);" onclick="app.delRow(${i})"></i>`:''}</div>`; for(let j=0;j<6;j++){ let day=["Mon","Tue","Wed","Thu","Fri","Sat"][j]; let val=(current.data[t]&&current.data[t][day])||""; g.innerHTML+=`<div class="tt-cell">${(state.isAdmin||state.isOwner||state.roles.timetableIncharge)?`<input class="tt-input" onchange="app.upTT('${t}','${day}',this.value)" value="${val}">`:val}</div>`; } }); },
    upTT(t,d,v){ let current=state.tt[state.dualTT]; if(!current.data[t]) current.data[t]={}; current.data[t][d]=v; },
    addTTRow(t){ if(t){ let current=state.tt[state.dualTT]; current.rows.push(t); this.renderTimeTable(); } },
    delRow(i){ let current=state.tt[state.dualTT]; current.rows.splice(i,1); this.renderTimeTable(); },
    async saveTT(){ let update={}; update[state.dualTT]=state.tt[state.dualTT]; await setDoc(doc(db,"settings","timetable"),update,{merge:true}); this.popup("Saved!"); },
    openSecretProgress(){ let b=document.getElementById('f-body'); let mySecrets=state.secretChats.filter(s=>s.user===state.user); let total=mySecrets.length; let replied=mySecrets.filter(s=>s.replies&&s.replies.length>0).length; b.innerHTML=`<div style="padding:20px;"><h3>Your Secret Progress</h3><div class="progress-container" style="margin:20px auto;"><div class="progress-ring" style="background:conic-gradient(var(--success) ${total?((replied/total)*100):0}%, #222 0%);"><div class="progress-val">${total}<span>Total</span></div></div></div><div class="stat-grid"><div class="stat-card"><h3>${total}</h3><p>Asked</p></div><div class="stat-card" style="border-color:var(--success);"><h3 style="color:var(--success);">${replied}</h3><p>Replies</p></div></div><button class="btn" style="width:100%; background:var(--primary);" onclick="app.openSecretChat()">Go to Secret Chat</button>${(state.isAdmin||state.isOwner)?`<button class="btn" style="width:100%; margin-top:10px; background:var(--accent);" onclick="app.viewAllSecrets()">View All Secrets</button>`:''}</div>`; },
    openSecretChat(){ let b=document.getElementById('f-body'); b.innerHTML=`<div class="chat-wrap"><div id="secret-feed" class="chat-feed" style="background:rgba(20,20,20,0.9);"></div><div class="chat-bar"><input id="secret-in" class="chat-in" placeholder="Ask a secret question..."><i class="fas fa-paper-plane" onclick="app.sendSecret()"></i></div></div>`; this.renderSecretChat(); this.initSecretSwipe(); },
    viewAllSecrets(){ let b=document.getElementById('f-body'); b.innerHTML='<div style="padding:20px;"><h3>All Secrets</h3></div>'; state.secretChats.forEach(s=>{ b.innerHTML+=`<div class="list-card" style="flex-direction:column; align-items:flex-start;"><div><span style="color:var(--accent);">${s.user}</span><span style="float:right;">${new Date(s.time).toLocaleDateString()}</span></div><p>${s.text}</p>${(state.isAdmin||state.isOwner)?`<i class="fas fa-trash del-icon" onclick="app.delItem('secret_chats','${s.id}')"></i>`:''}</div>`; }); b.innerHTML+=`<button class="btn" style="width:90%; margin:20px auto;" onclick="app.openSecretProgress()">Back</button>`; },
    renderSecretChat(){ let c=document.getElementById('secret-feed'); if(!c) return; c.innerHTML=''; state.secretChats.forEach(m=>{ if(m.deletedBy&&m.deletedBy.includes(state.user)) return; let mine=m.user===state.user; let pic=state.profiles[m.user]||`https://ui-avatars.com/api/?name=${m.user}`; if(!mine&&(!m.seenBy||!m.seenBy.includes(state.user))) updateDoc(doc(db,"secret_chats",m.id),{seenBy:arrayUnion(state.user)}).catch(()=>{}); c.innerHTML+=`<div class="msg-row ${mine?'mine':''}" data-msg-id="${m.id}">${!mine?`<img src="${pic}" class="chat-pfp">`:''}<div class="msg anonymous"><b>${state.isAdmin?`Anonymous (${m.user})`:'Anonymous Student'}</b><br>${m.text}<div style="font-size:0.6rem;margin-top:5px">${new Date(m.time).toLocaleString()}</div></div>${mine?`<img src="${pic}" class="chat-pfp">`:''}</div>`; }); if(c) c.scrollTop=c.scrollHeight; },
    initSecretSwipe(){ let feed=document.getElementById('secret-feed'); if(!feed) return; let startX; feed.addEventListener('touchstart',(e)=>{ startX=e.changedTouches[0].screenX; },{passive:true}); feed.addEventListener('touchend',(e)=>{ let diff=e.changedTouches[0].screenX-startX; if(Math.abs(diff)>80) this.openSecretProgress(); },{passive:true}); },
    async sendSecret(){ let v=document.getElementById('secret-in').value.trim(); if(v){ await addDoc(collection(db,"secret_chats"),{user:state.user,text:v,time:Date.now(),seenBy:[state.user],deletedBy:[]}); document.getElementById('secret-in').value=''; } },
    renderReportChatUI(b){ b.innerHTML=`<div class="chat-wrap"><div id="report-feed" class="chat-feed" style="background:rgba(20,20,20,0.9);"><div class="msg-row"><div class="msg report-bot"><b>Report Complaint</b><br>Submit your complaint. Attach images.</div></div></div><div class="chat-bar"><label><i class="fas fa-image" onclick="document.getElementById('report-file-input').click()"></i></label><input id="report-in" class="chat-in" placeholder="Type complaint..."><i class="fas fa-paper-plane" onclick="app.sendReport()"></i></div></div>`; this.renderReportChat(); },
    async sendReport(){ let v=document.getElementById('report-in').value.trim(); if(v||state.reportFile){ let feed=document.getElementById('report-feed'); let userMedia=state.reportFile?`<img src="${state.reportFile}" style="max-width:100%;border-radius:10px;"><br>`:''; feed.innerHTML+=`<div class="msg-row mine"><div class="msg mine">${userMedia}${v}</div></div>`; await addDoc(collection(db,"report_complaints"),{user:state.user,text:v,img:state.reportFile,time:Date.now(),status:'pending',resolved:false}); state.reportFile=null; document.getElementById('report-in').value=''; feed.scrollTop=feed.scrollHeight; } },
    renderReportChat(){ let c=document.getElementById('report-feed'); if(!c) return; c.innerHTML=''; state.reportComplaints.forEach(m=>{ let mine=m.user===state.user; let pic=state.profiles[m.user]||`https://ui-avatars.com/api/?name=${m.user}`; let media=m.img?`<img src="${m.img}" class="msg-img" onclick="app.viewMedia('${m.img}','image')">`:''; let resolveBtn=''; if((state.isAdmin||state.isOwner||state.roles.reportIncharge) && !m.resolved){ resolveBtn=`<button class="btn" style="background:var(--success);font-size:0.7rem;padding:4px 10px;" onclick="app.resolveReport('${m.id}')">Resolve</button>`; } c.innerHTML+=`<div class="msg-row ${mine?'mine':''}">${!mine?`<img src="${pic}" class="chat-pfp">`:''}<div class="msg ${mine?'mine':'theirs'}"><b>${m.user}</b><br>${media}${m.text}${resolveBtn}<div style="font-size:0.6rem;">${new Date(m.time).toLocaleString()}</div></div>${mine?`<img src="${pic}" class="chat-pfp">`:''}</div>`; }); },
    async resolveReport(id){ await updateDoc(doc(db,"report_complaints",id),{resolved:true,resolvedBy:state.user,resolvedAt:Date.now()}); this.popup("Report resolved"); },
    renderMessagesMenu(){ let b=document.getElementById('f-body'); b.innerHTML=''; let contacts=new Set(); contacts.add('admin'); if(state.isOwner) contacts.add('Kartik'); if(state.roles.chatIncharge) contacts.add(state.user); state.messages.forEach(m=>{ if(m.sender===state.user) contacts.add(m.receiver); if(m.receiver===state.user) contacts.add(m.sender); }); contacts.forEach(c=>{ if(c===state.user) return; let unread=state.messages.filter(m=>m.sender===c && m.receiver===state.user && !m.seen).length; let pic=state.profiles[c]||`https://ui-avatars.com/api/?name=${c}`; b.innerHTML+=`<div class="list-card" onclick="app.openDirectChat('${c}')"><div style="display:flex;align-items:center;gap:15px;"><img src="${pic}" style="width:45px;height:45px;border-radius:50%;"><b>${c}</b></div>${unread?`<div class="badge-notif">${unread}</div>`:''}</div>`; }); if(b.innerHTML==='') b.innerHTML='<p style="padding:20px;text-align:center;">No conversations yet.</p>'; },
    openDirectChat(target){ state.activeMsgUser=target; document.getElementById('f-title').innerText=`Chat with ${target}`; let b=document.getElementById('f-body'); b.innerHTML=`<div class="chat-wrap"><div id="dm-feed" class="chat-feed" style="background:transparent; padding-bottom:120px;"></div><div class="chat-bar"><textarea id="dm-in" class="chat-in" placeholder="Write message..."></textarea><i class="fas fa-paper-plane" onclick="app.sendDM()"></i></div></div>`; this.renderDirectMessages(); },
    renderDirectMessages(){ let c=document.getElementById('dm-feed'); if(!c) return; c.innerHTML=''; let msgs=state.messages.filter(m=>(m.sender===state.user&&m.receiver===state.activeMsgUser)||(m.sender===state.activeMsgUser&&m.receiver===state.user)); msgs.forEach(m=>{ let mine=m.sender===state.user; if(!mine&&!m.seen) updateDoc(doc(db,"messages",m.id),{seen:true}); let media=m.img?`<img src="${m.img}" style="max-width:100%;border-radius:8px;margin-bottom:10px;">`:''; c.innerHTML+=`<div class="letter-card ${mine?'mine':''}"><div class="letter-header"><span><b>To:</b> ${m.receiver}</span><span>${new Date(m.time).toLocaleString()}</span></div>${media}<div class="letter-body">${m.text.replace(/\n/g,'<br>')}</div><div class="letter-signature">From: ${m.sender}</div></div>`; }); c.scrollTop=c.scrollHeight; },
    async sendDM(){ let v=document.getElementById('dm-in').value.trim(); if(v||state.file){ await addDoc(collection(db,"messages"),{sender:state.user,receiver:state.activeMsgUser,text:v,img:state.file,time:Date.now(),seen:false}); document.getElementById('dm-in').value=''; state.file=null; } },
    renderChatUI(){ let c=document.getElementById('chat-bar-container'); if(!c) return; let isPriv=state.isAdmin||state.isOwner||state.vips.includes(state.user); let meetHtml=isPriv?`<i class="fas fa-video" style="color:#1a73e8;" onclick="app.modal('Host Meet',[{id:'t',label:'Subject'},{id:'l',label:'Meet Link'}],v=>app.sendMeet(v))"></i>`:''; let micHtml=`<i class="fas fa-microphone" style="color:var(--danger);" onclick="app.toggleRecording()"></i>`; if(state.chatMuted && !state.isAdmin && !state.isOwner){ c.innerHTML=`<div class="chat-bar" style="justify-content:center; background:rgba(239,68,68,0.1);"><span style="color:var(--danger);">Chat Paused by Admin</span></div>`; } else { c.innerHTML=`<div class="chat-bar">${meetHtml}${micHtml}<label><i class="fas fa-paperclip"></i><input type="file" id="chat-input" hidden accept="image/*,video/mp4,video/webm" onchange="app.sendFile(event,'chat')"></label><input id="c-in" class="chat-in" placeholder="Message..." oninput="app.startTyping()"><i class="fas fa-paper-plane" onclick="app.sendChat()"></i></div>`; } },
    async sendChat(){ if(state.chatMuted && !state.isAdmin && !state.isOwner) return this.popup("Chat muted"); let v=document.getElementById('c-in').value; if(v && BAD_WORDS.some(w=>v.toLowerCase().includes(w))){ await setDoc(doc(db,"settings","banned"),{list:[...state.banned,state.user],vips:state.vips}); return; } if(v||state.file){ await addDoc(collection(db,"chats"),{user:state.user,text:v,img:state.file,audio:null,time:Date.now(),replyTo:state.replyingTo?`${state.replyingTo.user}: ${state.replyingTo.text}`:null,deletedBy:[],seenBy:[state.user],reactions:[]}); document.getElementById('c-in').value=''; state.file=null; this.cancelReply(); this.stopTyping(); } },
    async sendMeet(v){ if(!v[0]||!v[1]) return; let html=`<div class="zoom-card"><div class="zoom-header"><i class="fas fa-video"></i> ${v[0]}</div><a href="${v[1]}" target="_blank" class="zoom-btn">Join Meet</a></div>`; await addDoc(collection(db,"chats"),{user:state.user,text:html,img:null,audio:null,time:Date.now(),replyTo:null,deletedBy:[],seenBy:[state.user],reactions:[]}); },
    renderChat(){ let c=document.getElementById('chat-feed'); if(!c) return; c.innerHTML=''; state.chats.forEach(m=>{ let mine=m.user===state.user; let pic=state.profiles[m.user]||`https://ui-avatars.com/api/?name=${m.user}`; let media=''; if(m.img){ if(m.img.startsWith('data:video')) media=`<video src="${m.img}" class="msg-vid" onclick="app.viewMedia('${m.img}','video')"></video>`; else media=`<img src="${m.img}" class="msg-img" onclick="app.viewMedia('${m.img}','image')">`; } if(m.audio) media=`<audio src="${m.audio}" controls class="audio-player"></audio><br>`; let reactionHtml=''; if(m.reactions&&m.reactions.length){ let counts={}; m.reactions.forEach(r=>counts[r.e]=(counts[r.e]||0)+1); reactionHtml=`<div class="reaction-container">`+Object.keys(counts).map(e=>`<div class="reaction-badge">${e} ${counts[e]>1?counts[e]:''}</div>`).join('')+`</div>`; } c.innerHTML+=`<div class="msg-row ${mine?'mine':''}">${!mine?`<img src="${pic}" class="chat-pfp">`:''}<div class="msg ${mine?'mine':'theirs'}" onclick="app.msgOpt('${m.id}','${m.user}','${(m.text||'').replace(/'/g,"\\'")}')"><b>${m.user}</b> ${state.vips.includes(m.user)?'<span class="vip-tag">VIP</span>':''} ${m.user==='admin'?'<span class="admin-tag">ADMIN</span>':''}<br>${m.replyTo?`<div class="quoted-msg"><b>Replying:</b><br>${m.replyTo}</div>`:''}${media}${m.text||'Audio note'}<div style="font-size:0.6rem;">${new Date(m.time).toLocaleTimeString()}</div>${reactionHtml}</div>${mine?`<img src="${pic}" class="chat-pfp">`:''}</div>`; }); c.scrollTop=c.scrollHeight; },
    startTyping(){ updateDoc(doc(db,"settings","typing"),{users:arrayUnion(state.user)}).catch(()=>{}); clearTimeout(state.typingTimeout); state.typingTimeout=setTimeout(()=>updateDoc(doc(db,"settings","typing"),{users:arrayRemove(state.user)}).catch(()=>{}),2000); },
    stopTyping(){ clearTimeout(state.typingTimeout); updateDoc(doc(db,"settings","typing"),{users:arrayRemove(state.user)}).catch(()=>{}); },
    msgOpt(id,user,text){ state.selectedMsg={id,user,text}; document.getElementById('btn-msg-del-everyone').style.display=(state.isAdmin||state.isOwner||user===state.user)?'flex':'none'; document.getElementById('msg-options').style.display='flex'; },
    showInfo(){ document.getElementById('msg-options').style.display='none'; getDoc(doc(db,"chats",state.selectedMsg.id)).then(snap=>{ let seen=snap.exists()?snap.data().seenBy:[]; let list=seen.filter(u=>u!==state.selectedMsg.user); this.popup(`Seen by:\n${list.length?list.join('\n'):'Nobody'}`); }); },
    doReply(){ state.replyingTo=state.selectedMsg; document.getElementById('msg-options').style.display='none'; let bar=document.getElementById('reply-bar'); if(bar){ bar.style.display='flex'; bar.querySelector('span').innerText=`Replying to ${state.replyingTo.user}...`; } },
    cancelReply(){ state.replyingTo=null; let bar=document.getElementById('reply-bar'); if(bar) bar.style.display='none'; },
    async doDelMsg(mode){ document.getElementById('msg-options').style.display='none'; if(mode==='everyone'){ if(state.isAdmin||state.isOwner||state.selectedMsg.user===state.user) this.popup("Delete for everyone?",'confirm',async()=>await deleteDoc(doc(db,"chats",state.selectedMsg.id))); } else { await updateDoc(doc(db,"chats",state.selectedMsg.id),{deletedBy:arrayUnion(state.user)}); } },
    copyMessage(){ let text=state.selectedMsg.text; navigator.clipboard.writeText(text); this.popup("Copied!"); document.getElementById('msg-options').style.display='none'; },
    showReactions(){ document.getElementById('msg-options').style.display='none'; document.getElementById('reaction-picker').style.display='flex'; },
    async addReaction(emoji){ document.getElementById('reaction-picker').style.display='none'; if(!state.selectedMsg) return; let ref=doc(db,"chats",state.selectedMsg.id); let snap=await getDoc(ref); if(snap.exists()){ let existing=(snap.data().reactions||[]).find(r=>r.u===state.user&&r.e===emoji); if(existing) await updateDoc(ref,{reactions:arrayRemove(existing)}); else await updateDoc(ref,{reactions:arrayUnion({u:state.user,e:emoji})}); } },
    compressImage(file,callback){ let reader=new FileReader(); reader.readAsDataURL(file); reader.onload=(e)=>{ let img=new Image(); img.src=e.target.result; img.onload=()=>{ let canvas=document.createElement('canvas'); let scale=800/img.width; canvas.width=800; canvas.height=img.height*scale; canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height); callback(canvas.toDataURL('image/jpeg',0.7)); }; }; },
    sendFile(e,target){ let f=e.target.files[0]; if(f){ this.compressImage(f,(base64)=>{ state.file=base64; if(target==='chat') this.sendChat(); else this.sendDM(); }); } },
    async toggleRecording(){ if(!state.isRecording){ try{ let stream=await navigator.mediaDevices.getUserMedia({audio:true}); state.mediaRecorder=new MediaRecorder(stream); state.audioChunks=[]; state.mediaRecorder.ondataavailable=e=>state.audioChunks.push(e.data); state.mediaRecorder.onstop=async()=>{ clearInterval(state.recTimer); document.getElementById('recording-overlay').style.display='none'; if(state.shouldSendAudio&&state.recSecs>0){ let blob=new Blob(state.audioChunks,{type:'audio/webm'}); let reader=new FileReader(); reader.readAsDataURL(blob); reader.onloadend=async()=>{ await addDoc(collection(db,"chats"),{user:state.user,text:"",audio:reader.result,time:Date.now(),deletedBy:[],seenBy:[state.user],reactions:[]}); }; } stream.getTracks().forEach(t=>t.stop()); }; state.mediaRecorder.start(); state.isRecording=true; state.recSecs=0; state.shouldSendAudio=false; document.getElementById('recording-overlay').style.display='flex'; document.getElementById('rec-time').innerText="0:00"; state.recTimer=setInterval(()=>{ state.recSecs++; let m=Math.floor(state.recSecs/60); let s=String(state.recSecs%60).padStart(2,'0'); document.getElementById('rec-time').innerText=`${m}:${s}`; },1000); } catch(e){ this.popup("Microphone permission needed"); } } },
    stopRecording(send){ if(state.mediaRecorder&&state.isRecording){ state.shouldSendAudio=send; state.mediaRecorder.stop(); state.isRecording=false; } },
    renderHomework(){ let b=document.getElementById('f-body'); b.innerHTML=''; if(state.isAdmin||state.isOwner||state.roles.homeworkIncharge){ b.innerHTML=`<button class="btn" style="width:100%;margin-bottom:10px;background:var(--primary);" onclick="app.modal('Post Homework',[{id:'s',label:'Subject'},{id:'t',label:'Title'},{id:'d',label:'Description'},{id:'date',label:'Due Date (YYYY-MM-DD)'},{id:'link',label:'Test Link (optional)'}],v=>app.postHomework(v))">+ Create Assignment</button><button class="btn" style="width:100%;margin-bottom:20px;background:#333;" onclick="document.getElementById('hw-file-input').click()">Attach Files (${state.hwFilesTemp.length})</button>`; } state.homework.forEach(hw=>{ let hasImgs=hw.images&&hw.images.length; let userProg=hw.progress&&hw.progress[state.user]; let completed=userProg&&userProg.completed; b.innerHTML+=`<div class="hw-card ${completed?'completed':''}" onclick="app.viewHomework('${hw.id}')"><div class="hw-icon-wrap"><i class="fas fa-book-open"></i></div><div class="hw-content"><div class="hw-top"><span class="hw-subject">${hw.sub}</span><span class="hw-date">${hw.date}</span></div><div class="hw-title">${hw.title}</div><div class="hw-desc">${hw.desc}</div>${completed?`<div class="completion-date"><i class="fas fa-check-circle"></i> Done on ${userProg.date}</div>`:''}</div><div class="hw-actions"><div class="hw-btns"><div class="hw-btn"><i class="fas fa-share-alt"></i></div><div class="hw-btn">${hasImgs?`<i class="fas fa-paperclip"></i><div class="hw-badge">${hw.images.length}</div>`:'<i class="fas fa-paperclip"></i>'}</div>${(!state.isAdmin&&!completed)?`<div class="hw-btn complete" onclick="event.stopPropagation(); app.markHomeworkDone('${hw.id}')"><i class="fas fa-check"></i></div>`:''}</div><div class="hw-uploader">by ${hw.uploader}</div></div>${(state.isAdmin||state.isOwner||state.roles.homeworkIncharge)?`<i class="fas fa-trash del-icon" style="position:absolute;bottom:10px;right:10px;" onclick="event.stopPropagation(); app.delItem('homework','${hw.id}')"></i>`:''}</div>`; }); },
    async postHomework(v){ if(!v[0]||!v[1]) return; await addDoc(collection(db,"homework"),{sub:v[0],title:v[1],desc:v[2],date:v[3]||getLocalDate(),testLink:v[4]||'',images:state.hwFilesTemp,time:Date.now(),uploader:state.user,progress:{}}); state.hwFilesTemp=[]; this.popup("Homework posted!"); this.renderHomework(); },
    async markHomeworkDone(id){ let hw=state.homework.find(h=>h.id===id); if(!hw) return; let prog=hw.progress||{}; prog[state.user]={completed:true,date:formatDate(Date.now())}; await updateDoc(doc(db,"homework",id),{progress:prog}); this.popup("Marked done!"); this.renderHomework(); },
    viewHomework(id){ let hw=state.homework.find(h=>h.id===id); if(!hw) return; state.modalType='homework-detail'; document.getElementById('f-title').innerText="Assignment"; let b=document.getElementById('f-body'); let imgHtml=''; if(hw.images&&hw.images.length){ imgHtml=`<div class="hw-attach-grid" style="display:grid; grid-template-columns:repeat(auto-fill,minmax(100px,1fr)); gap:10px;">`+hw.images.map((img,i)=>`<div onclick="app.viewMedia('${img}','image')"><img src="${img}" style="width:100%; border-radius:12px;"></div>`).join('')+`</div>`; } let comp=hw.progress&&hw.progress[state.user]; b.innerHTML=`<div style="padding:20px;"><h2>${hw.sub}</h2><p><strong>Due:</strong> ${hw.date}</p><p>${hw.title}</p><p>${hw.desc}</p>${hw.testLink?`<a href="${hw.testLink}" target="_blank" class="btn" style="background:var(--accent); margin:10px 0;">Take Test</a>`:''}${imgHtml}${(!state.isAdmin&&!comp?.completed)?`<button class="btn" style="background:var(--success); margin-top:20px;" onclick="app.markHomeworkDone('${id}')">Mark Done</button>`:''}</div>`; },
    renderSchoolWork(){ let b=document.getElementById('f-body'); b.innerHTML=''; if(state.isAdmin||state.isOwner||state.roles.homeworkIncharge){ b.innerHTML=`<button class="btn" style="width:100%;margin-bottom:15px;background:var(--primary);" onclick="app.modal('Add School Work',[{id:'title',label:'Title'},{id:'link',label:'Link'},{id:'desc',label:'Description'}],v=>app.addSchoolWork(v))">+ Add Work</button>`; } b.innerHTML+=`<div class="school-work-grid" id="school-work-grid"></div>`; this.renderSchoolWorkGrid(); },
    renderSchoolWorkGrid(){ let grid=document.getElementById('school-work-grid'); if(!grid) return; grid.innerHTML=''; state.schoolWork.forEach(work=>{ let completed=work.completedBy&&work.completedBy[state.user]?.completed; grid.innerHTML+=`<div class="school-work-card ${completed?'completed':''}"><i class="fas fa-link"></i><span class="school-work-title">${work.title}</span><a href="${work.link}" target="_blank" class="school-work-link">Open</a>${!completed&&(!state.isAdmin)?`<button class="btn" style="background:var(--success); padding:5px 10px;" onclick="app.markWorkDone('${work.id}')">Done</button>`:''}${(state.isAdmin||state.isOwner||state.roles.homeworkIncharge)?`<i class="fas fa-trash del-icon" onclick="app.delItem('school_work','${work.id}')"></i>`:''}</div>`; }); },
    async addSchoolWork(v){ if(!v[0]||!v[1]) return; await addDoc(collection(db,"school_work"),{title:v[0],link:v[1],desc:v[2]||'',time:Date.now(),uploadedBy:state.user,completedBy:{}}); this.popup("Added"); this.open('school-work'); },
    async markWorkDone(id){ let work=state.schoolWork.find(w=>w.id===id); if(!work) return; let completedBy=work.completedBy||{}; completedBy[state.user]={completed:true,date:formatDate(Date.now())}; await updateDoc(doc(db,"school_work",id),{completedBy}); this.popup("Marked done!"); this.renderSchoolWorkGrid(); },
    renderProgressDashboard(){ let b=document.getElementById('f-body'); let totalH=state.homework.length; let doneH=state.homework.filter(h=>h.progress&&h.progress[state.user]?.completed).length; let attP=0,totalAtt=0; for(let d in state.attn){ if(state.attn[d][state.user]){ totalAtt++; if(state.attn[d][state.user]==='P') attP++; } } let percent=totalAtt?Math.round((attP/totalAtt)*100):0; let entabBtn=`<button class="btn" style="width:100%; background:var(--accent); margin-top:20px;" onclick="app.openEntab()">Open Entab</button>`; b.innerHTML=`<div style="padding:20px;"><h3>Your Progress</h3><div class="progress-container"><div class="progress-ring" style="background:conic-gradient(var(--success) ${percent}%, #222 0%);"><div class="progress-val">${percent}%</div></div></div><div class="stat-grid"><div class="stat-card"><h3>${doneH}/${totalH}</h3><p>Homework</p></div><div class="stat-card"><h3>${attP}/${totalAtt}</h3><p>Attendance</p></div></div>${entabBtn}</div>`; },
    openEntab(){ let browser=document.getElementById('inapp-browser'); let iframe=document.getElementById('inapp-iframe'); iframe.src='https://entab.online/empros'; browser.style.display='flex'; },
    renderAttendanceDash(b){ let d=getLocalDate(); if(state.isAdmin||state.isOwner||state.roles.attendanceIncharge){ let p=0,a=0,l=0; USERS.forEach(u=>{ if(u!=='Guest'&&u!=='admin'){ let s=(state.attn[d]||{})[u]; if(s==='P') p++; else if(s==='A') a++; else if(s==='H'||s==='HD') l++; } }); b.innerHTML=`<div><div class="attn-date-bar"><span>Date:</span><input type="date" id="attn-date" value="${state.selectedDate}" onchange="app.changeDate(this.value)"></div><div id="attn-list"></div></div>`; this.renderAdminAttn(); } else { let p=0,a=0,l=0,total=0; for(let dt in state.attn){ if(state.attn[dt][state.user]){ total++; if(state.attn[dt][state.user]==='P') p++; else if(state.attn[dt][state.user]==='A') a++; else l++; } } let pc=total?Math.round((p/total)*100):0; b.innerHTML=`<div class="attn-dash-wrap"><div class="progress-container"><div class="progress-ring" style="background:conic-gradient(var(--success) ${pc}%, #222 0%);"><div class="progress-val">${pc}%</div></div></div><div class="stat-grid"><div class="stat-card absent"><h3>${a}</h3><p>Absent</p></div><div class="stat-card leave"><h3>${l}</h3><p>Leave/HD</p></div></div></div>`; } },
    renderAdminAttn(){ let c=document.getElementById('attn-list'); if(!c||!state.selectedDate) return; c.innerHTML=''; let data=state.attn[state.selectedDate]||{}; USERS.forEach(u=>{ if(u==='admin'||u==='Guest') return; let s=data[u]; let pic=state.profiles[u]||`https://ui-avatars.com/api/?name=${u}`; c.innerHTML+=`<div class="st-card"><div class="st-head"><img src="${pic}" class="st-face"><span>${u}</span></div><div class="st-acts"><div class="act-btn ${s==='P'?'active-P':''}" onclick="app.mark('${state.selectedDate}','${u}','P')">P</div><div class="act-btn ${s==='A'?'active-A':''}" onclick="app.mark('${state.selectedDate}','${u}','A')">A</div><div class="act-btn ${s==='HD'?'active-HD':''}" onclick="app.mark('${state.selectedDate}','${u}','HD')">HD</div><div class="act-btn ${s==='H'?'active-H':''}" onclick="app.mark('${state.selectedDate}','${u}','H')">H</div></div></div>`; }); },
    changeDate(v){ state.selectedDate=v; this.renderAdminAttn(); },
    async mark(d,u,s){ let n=state.attn[d]||{}; n[u]=s; state.attn[d]=n; await setDoc(doc(db,"attendance_log",d),n); this.renderAdminAttn(); },
    openAttn(){ let m=document.getElementById('feature-modal'); m.style.display='flex'; document.getElementById('f-title').innerText="Mark Attendance"; document.getElementById('f-body').innerHTML=`<div style="padding:20px;"><div class="attn-date-bar"><span>Date:</span><input type="date" id="attn-date" value="${state.selectedDate}" onchange="app.changeDate(this.value)"></div><div id="attn-list"></div><div style="margin-top:20px;"><button class="btn" onclick="app.longPressRange()">Set Holiday Range</button></div></div>`; this.renderAdminAttn(); },
    longPressRange(){ this.popup("Select start date and end date for holiday/vacation",'confirm',()=>{ this.modal("Holiday Range",[{id:'start',label:'Start Date (YYYY-MM-DD)'},{id:'end',label:'End Date (YYYY-MM-DD)'},{id:'reason',label:'Reason'}],async(v)=>{ if(!v[0]||!v[1]) return; let start=new Date(v[0]); let end=new Date(v[1]); let newHols={...state.holidays}; for(let d=start;d<=end;d.setDate(d.getDate()+1)){ let dat=d.toISOString().slice(0,10); newHols[dat]=v[2]||'Holiday'; } await setDoc(doc(db,"settings","holidays"),newHols); this.popup("Holidays marked!"); }); }); },
    addTeacherWithImage(){ let input=document.getElementById('teacher-image-input'); input.onchange=(e)=>{ let f=e.target.files[0]; if(f){ this.compressImage(f,(base64)=>{ state.teacherImageFile=base64; this.modal('Add Teacher',[{id:'s',label:'Subject'},{id:'n',label:'Name'},{id:'p',label:'Phone'}],v=>this.addTeacher(v,state.teacherImageFile)); }); } }; input.click(); },
    async addTeacher(v,img){ if(!v[0]||!v[1]||!v[2]) return; await addDoc(collection(db,"teachers"),{sub:v[0],name:v[1],phone:v[2],img:img||null}); this.popup("Teacher added"); this.open('teach'); },
    editTeacher(id){ let t=state.teachers.find(t=>t.id===id); if(!t) return; let input=document.getElementById('teacher-image-input'); input.onchange=(e)=>{ let f=e.target.files[0]; if(f){ this.compressImage(f,(base64)=>{ state.teacherImageFile=base64; this.modal('Edit Teacher',[{id:'s',label:'Subject'},{id:'n',label:'Name'},{id:'p',label:'Phone'}],v=>this.updateTeacher(id,v,state.teacherImageFile)); }); } else { this.modal('Edit Teacher',[{id:'s',label:'Subject'},{id:'n',label:'Name'},{id:'p',label:'Phone'}],v=>this.updateTeacher(id,v,t.img)); } }; input.click(); },
    async updateTeacher(id,v,img){ await updateDoc(doc(db,"teachers",id),{sub:v[0],name:v[1],phone:v[2],img}); this.popup("Updated"); this.open('teach'); },
    renderTeachers(){ let c=document.getElementById('teach-list'); if(!c) return; c.innerHTML=''; state.teachers.forEach(t=>{ let imgSrc=t.img||`https://ui-avatars.com/api/?name=${t.name}`; c.innerHTML+=`<div class="teacher-card"><img src="${imgSrc}" class="teacher-avatar" onclick="app.viewMedia('${imgSrc}','image')"><div class="teacher-info"><div class="subject">${t.sub}</div><div class="name">${t.name}</div><div class="phone">${t.phone}</div></div><div class="teacher-actions">${(state.isOwner||state.isAdmin)?`<i class="fas fa-pencil-alt" style="color:var(--accent);cursor:pointer;" onclick="app.editTeacher('${t.id}')"></i><i class="fas fa-trash del-icon" onclick="app.delItem('teachers','${t.id}')"></i>`:`<a href="tel:${t.phone}" style="color:var(--success);font-size:1.5rem;"><i class="fas fa-phone"></i></a><a href="https://wa.me/${t.phone}" target="_blank" style="color:#25D366;"><i class="fab fa-whatsapp"></i></a>`}</div></div>`; }); },
    renderCal(){ let m=document.getElementById('cal-month'); if(!m) return; let d=new Date(); m.innerText=d.toLocaleString('default',{month:'long'}); let g=document.getElementById('cal-grid'); g.innerHTML=''; let year=d.getFullYear(), month=d.getMonth(), days=new Date(year,month+1,0).getDate(), start=new Date(year,month,1).getDay(); for(let i=0;i<start;i++) g.innerHTML+=`<div></div>`; for(let i=1;i<=days;i++){ let k=`${year}-${String(month+1).padStart(2,'0')}-${String(i).padStart(2,'0')}`; let dots='', classes='day'; if(state.holidays[k]){ classes+=' holiday-cell'; dots+=`<div class="dot dot-hol"></div>`; } if(state.attn[k]&&state.attn[k][state.user]){ let s=state.attn[k][state.user]; if(s==='P') dots+=`<div class="dot dot-p"></div>`; else if(s==='A'){ classes+=' absent-cell'; dots+=`<div class="dot dot-a"></div>`; } else if(s==='HD') dots+=`<div class="dot dot-hd"></div>`; } if(state.events.find(e=>e.date===k)) dots+=`<div class="dot dot-e"></div>`; if(state.exam&&state.exam.date===k) dots+=`<div class="dot dot-a"></div>`; if(i===d.getDate()) classes+=' today'; g.innerHTML+=`<div class="${classes}" onclick="app.clickDate('${k}')">${i}<div class="dots-row">${dots}</div></div>`; } },
    clickDate(dateStr){ let hol=state.holidays[dateStr]; if(state.isAdmin||state.isOwner||state.roles.attendanceIncharge){ if(hol){ this.popup(`Remove holiday?`,'confirm',async()=>{ let newHols={...state.holidays}; delete newHols[dateStr]; await setDoc(doc(db,"settings","holidays"),newHols); }); } else { this.modal(`Mark Holiday`, [{id:'reason',label:'Reason'}], async(v)=>{ let newHols={...state.holidays, [dateStr]:v[0]||'Holiday'}; await setDoc(doc(db,"settings","holidays"),newHols); }); } } else { let info=[]; if(hol) info.push(`🏖️ Holiday: ${hol}`); let ev=state.events.find(e=>e.date===dateStr); if(ev) info.push(`📅 Event: ${ev.title}`); if(state.exam&&state.exam.date===dateStr) info.push(`🚨 Exam: ${state.exam.name}`); if(state.attn[dateStr]&&state.attn[dateStr][state.user]){ let s=state.attn[dateStr][state.user]; info.push(`Attendance: ${s==='P'?'Present':s==='A'?'Absent':'Leave'}`); } if(info.length) this.popup(info.join('\n')); else this.popup(`No data for ${dateStr}`); } },
    renderScheduleBoard(){ let today=getLocalDate(); let upcoming=[...state.events.filter(e=>e.date>=today), ...(state.exam&&state.exam.date>=today?[{title:state.exam.name,date:state.exam.date,isExam:true}]:[])]; upcoming.sort((a,b)=>a.date.localeCompare(b.date)); let next=upcoming[0]; let board=document.getElementById('schedule-board'); let badge=document.getElementById('schedule-badge'); let txt=document.getElementById('schedule-text'); let delBtn=document.getElementById('schedule-del-btn'); if(next){ board.className=next.isExam?'glass board-exam':'glass board-event'; badge.innerText=next.isExam?'EXAM':'EVENT'; txt.innerText=`${next.title} (${next.date})`; if(state.isAdmin||state.isOwner){ delBtn.style.display='block'; delBtn.onclick=()=>next.isExam?deleteDoc(doc(db,"settings","exam")):deleteDoc(doc(db,"events",next.id)); } else delBtn.style.display='none'; } else { board.className='glass'; badge.innerText='SCHEDULE'; txt.innerText="No Upcoming Schedule"; delBtn.style.display='none'; } },
    async addSchedule(v){ if(!v[0]||!v[1]||!v[2]) return; if(v[0].toLowerCase()==='exam') await setDoc(doc(db,"settings","exam"),{name:v[1],date:v[2]}); else await addDoc(collection(db,"events"),{title:v[1],date:v[2]}); this.popup("Added"); },
    delSchedule(){ let today=getLocalDate(); let upcoming=[...state.events, ...(state.exam?[{...state.exam,isExam:true}]:[])].filter(e=>e.date>=today).sort((a,b)=>a.date.localeCompare(b.date)); let next=upcoming[0]; if(next) this.popup("Delete?",'confirm',async()=>{ if(next.isExam) await deleteDoc(doc(db,"settings","exam")); else await deleteDoc(doc(db,"events",next.id)); }); },
    async toggleChatMute(){ let newMute=!state.chatMuted; await setDoc(doc(db,"settings","chat"),{muted:newMute},{merge:true}); this.popup(`Chat ${newMute?'MUTED':'UNMUTED'}`); },
    openBan(){ let m=document.getElementById('feature-modal'); m.style.display='flex'; document.getElementById('f-title').innerText="User Management"; let b=document.getElementById('f-body'); b.innerHTML='<div style="padding:20px;"></div>'; let c=b.firstChild; USERS.forEach(u=>{ if(u==='admin'||u==='Guest') return; let isBan=state.banned.includes(u); let isVip=state.vips.includes(u); let role=state.roles[u]||'user'; c.innerHTML+=`<div class="list-card"><div><b>${u}</b> ${isVip?'<span class="vip-tag">VIP</span>':''} <span class="badge-notif">${role}</span></div><div style="display:flex; gap:8px;">${(state.isOwner||state.isAdmin)?`<button class="btn" style="background:var(--accent);padding:5px 12px;" onclick="app.resetPass('${u}')">Reset Pass</button><button class="btn" style="background:${isVip?'#ffd700':'#333'};" onclick="app.toggleVIP('${u}')">VIP</button><button class="btn" style="background:${isBan?'var(--success)':'var(--danger)'};" onclick="app.toggleBan('${u}')">${isBan?'Unban':'Ban'}</button>`:''}${state.isOwner?`<button class="btn" style="background:var(--primary);" onclick="app.setRole('${u}')">Set Role</button>`:''}</div></div>`; }); },
    async resetPass(u){ this.modal(`Reset Password for ${u}`, [{id:'p',label:'New Password'}], async(v)=>{ if(v[0]){ await setDoc(doc(db,"users",u),{password:v[0]},{merge:true}); this.popup("Password changed"); } }); },
    async toggleVIP(u){ let newVips=[...state.vips]; if(newVips.includes(u)) newVips=newVips.filter(x=>x!==u); else newVips.push(u); await setDoc(doc(db,"settings","banned"),{list:state.banned, vips:newVips}); this.openBan(); },
    async toggleBan(u){ let newBan=[...state.banned]; if(newBan.includes(u)) newBan=newBan.filter(x=>x!==u); else newBan.push(u); await setDoc(doc(db,"settings","banned"),{list:newBan, vips:state.vips}); this.openBan(); },
    setRole(u){ this.modal(`Set Role for ${u}`, [{id:'role',label:'Role (admin/viceadmin/incharge_notes/incharge_homework/incharge_attendance/incharge_chat/incharge_reports)'}],async(v)=>{ await setDoc(doc(db,"users",u),{role:v[0]},{merge:true}); this.popup("Role updated"); this.openBan(); }); },
    manageReportIncharges(){ this.openBan(); this.popup("Assign report incharge via Set Role: incharge_reports"); },
    clearAttendanceYear(){ if(!(state.isAdmin||state.isOwner)) return; this.modal("Clear Attendance Year",[{id:'year',label:'Year (YYYY)'}],async(v)=>{ let year=v[0]; let batch=writeBatch(db); let count=0; for(let d in state.attn){ if(d.startsWith(year)){ batch.delete(doc(db,"attendance_log",d)); count++; } } if(count) await batch.commit(); this.popup(`Deleted ${count} records`); }); },
    exportAttendanceCSV(){ let csv="Date,"+USERS.filter(u=>u!=='admin'&&u!=='Guest').join(",")+"\n"; Object.keys(state.attn).sort().forEach(d=>{ csv+=d+USERS.filter(u=>u!=='admin'&&u!=='Guest').map(u=>","+(state.attn[d][u]||"-")).join('')+"\n"; }); let blob=new Blob([csv],{type:'text/csv'}); let a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download="attendance.csv"; a.click(); },
    addFolder(type,name){ let s={...state.structure}; if(!s[type]) s[type]={}; if(!s[type][name]) s[type][name]=[]; setDoc(doc(db,"settings","structure"),s).then(()=>this.open(type)); },
    delFolder(type,name){ this.popup(`Delete ${name}?`,'confirm',async()=>{ let s={...state.structure}; delete s[type][name]; await setDoc(doc(db,"settings","structure"),s); this.open(type); }); },
    addChapter(type,folder,chap){ let s={...state.structure}; if(!s[type][folder].includes(chap)) s[type][folder].push(chap); setDoc(doc(db,"settings","structure"),s).then(()=>this.openSubject(type,folder)); },
    delChapter(type,folder,chap){ let s={...state.structure}; s[type][folder]=s[type][folder].filter(c=>c!==chap); setDoc(doc(db,"settings","structure"),s).then(()=>this.openSubject(type,folder)); },
    openSubject(type,folder){ state.currentSubject=folder; document.getElementById('f-subtitle').innerText=folder; let b=document.getElementById('f-body'); let html='<div style="padding:20px;">'; if(state.isAdmin||state.isOwner||state.roles[type+'Incharge']) html+=`<button class="btn" style="width:100%;margin-bottom:20px;background:var(--primary);" onclick="app.modal('New Chapter',[{id:'c',label:'Chapter Name'}],v=>app.addChapter('${type}','${folder}',v[0]))">Create Chapter</button>`; (state.structure[type][folder]||[]).forEach(c=>{ html+=`<div class="chapter-item" onclick="app.openChapter('${type}','${folder}','${c}')"><span class="chapter-title">${c}</span><div>${(state.isAdmin||state.isOwner||state.roles[type+'Incharge'])?`<i class="fas fa-trash del-icon" style="margin-right:15px;" onclick="event.stopPropagation(); app.delChapter('${type}','${folder}','${c}')"></i>`:''}<i class="fas fa-chevron-right"></i></div></div>`; }); b.innerHTML=html+'</div>'; },
    openChapter(type,folder,chap){ state.currentChapter=chap; document.getElementById('f-subtitle').innerText=`${folder} > ${chap}`; let b=document.getElementById('f-body'); b.innerHTML='<div style="padding:20px;"></div>'; let c=b.firstChild; if(state.isAdmin||state.isOwner||state.roles[type+'Incharge']) c.innerHTML=`<button class="btn" style="width:100%;margin-bottom:20px;background:var(--success);" onclick="app.modal('Add Material',[{id:'t',label:'Title'},{id:'d',label:'Drive Link'},{id:'y',label:'YouTube URL'},{id:'b',label:'Book Link'},{id:'o',label:'Other Link'}],v=>app.addRes('${type}','${folder}','${chap}',v))">Add Material</button>`; let list=state.resources.filter(r=>r.type===type&&r.folder===folder&&r.chap===chap); list.forEach(r=>{ let btns=''; if(r.drive) btns+=`<button class="res-btn res-btn-drive" onclick="window.open('${r.drive}')"><i class="fas fa-link"></i> Drive</button>`; if(r.yt) btns+=`<button class="res-btn res-btn-yt" onclick="app.viewYt('${r.yt}')"><i class="fab fa-youtube"></i> Video</button>`; if(r.book) btns+=`<button class="res-btn res-btn-book" onclick="window.open('${r.book}')"><i class="fas fa-book"></i> Book</button>`; if(r.other) btns+=`<button class="res-btn res-btn-other" onclick="window.open('${r.other}')"><i class="fas fa-external-link-alt"></i> Other</button>`; c.innerHTML+=`<div class="resource-card"><div class="res-head"><span>${r.title}</span><div>${(state.isAdmin||state.isOwner||state.roles[type+'Incharge'])?`<i class="fas fa-pencil-alt" style="margin-right:10px;" onclick="app.editRes('${r.id}')"></i><i class="fas fa-trash del-icon" onclick="app.delItem('resources','${r.id}')"></i>`:''}</div></div><div class="res-actions">${btns}</div></div>`; }); },
    editRes(id){ let res=state.resources.find(r=>r.id===id); if(!res) return; this.modal('Edit Material',[{id:'t',label:'Title',value:res.title},{id:'d',label:'Drive Link',value:res.drive||''},{id:'y',label:'YouTube URL',value:res.yt||''},{id:'b',label:'Book Link',value:res.book||''},{id:'o',label:'Other Link',value:res.other||''}],async(v)=>{ await updateDoc(doc(db,"resources",id),{title:v[0],drive:v[1],yt:v[2],book:v[3],other:v[4]}); this.popup("Updated"); this.openChapter(state.modalType,state.currentSubject,state.currentChapter); }); },
    async addRes(type,folder,chap,v){ await addDoc(collection(db,"resources"),{type,folder,chap,title:v[0],drive:v[1]||"",yt:v[2]||"",book:v[3]||"",other:v[4]||""}); this.popup("Added"); },
    viewYt(url){ let id=url.match(/(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/)?.[1]; if(id){ document.getElementById('media-viewer').style.display='flex'; document.getElementById('yt-container').style.display='block'; document.getElementById('media-iframe').src=`https://www.youtube.com/embed/${id}?autoplay=1`; } else this.popup("Invalid YouTube URL"); },
    viewMedia(src,type){ let v=document.getElementById('media-viewer'); v.style.display='flex'; document.getElementById('media-download').href=src; document.getElementById('yt-container').style.display='none'; if(type==='video'){ document.getElementById('media-img').style.display='none'; let vid=document.getElementById('media-vid'); vid.style.display='block'; vid.src=src; vid.play(); } else { document.getElementById('media-vid').style.display='none'; let img=document.getElementById('media-img'); img.style.display='block'; img.src=src; } },
    closeMedia(){ document.getElementById('media-viewer').style.display='none'; let vid=document.getElementById('media-vid'); vid.pause(); vid.src=''; document.getElementById('media-img').src=''; document.getElementById('media-iframe').src=''; document.getElementById('yt-container').style.display='none'; },
    delItem(col,id){ this.popup("Delete?",'confirm',async()=>await deleteDoc(doc(db,col,id))); },
    modal(title,fields,cb){ document.getElementById('im-title').innerText=title; let c=document.getElementById('im-fields'); c.innerHTML=''; fields.forEach(f=>{ let val=f.value||''; c.innerHTML+=`<input id="mi-${f.id}" class="modal-field" placeholder="${f.label}" value="${val}">`; }); document.getElementById('input-modal').style.display='flex'; document.getElementById('im-save').onclick=()=>{ let vals=fields.map(f=>document.getElementById(`mi-${f.id}`).value); if(vals[0]){ cb(vals); document.getElementById('input-modal').style.display='none'; } else this.popup("Required field empty!"); }; },
    renderAnn(){ let c=document.getElementById('ann-feed'); if(!c) return; c.innerHTML=''; state.anns.forEach(a=>{ c.innerHTML+=`<div class="list-card" style="display:block;"><div><span style="color:var(--accent);"><i class="fas fa-bullhorn"></i> ANNOUNCEMENT</span> <small>${new Date(a.time).toLocaleDateString()}</small></div><p>${a.text}</p>${a.img?`<img src="${a.img}" style="width:100%;border-radius:14px;margin-top:10px;" onclick="app.viewMedia('${a.img}','image')">`:''}${a.file?`<a href="${a.file}" download class="btn" style="margin-top:10px;">Download Attachment</a>`:''}${(state.isAdmin||state.isOwner||state.roles.announcementIncharge)?`<div style="text-align:right"><i class="fas fa-trash del-icon" onclick="app.delItem('announcements','${a.id}')"></i></div>`:''}</div>`; }); },
    async handleAnnFile(e){ let files=e.target.files; if(files.length){ let file=files[0]; if(file.type.startsWith('video/')){ let reader=new FileReader(); reader.readAsDataURL(file); reader.onloadend=()=>{ state.file=reader.result; this.popup("Video attached"); }; } else { this.compressImage(file,(base64)=>{ state.file=base64; this.popup("Image attached"); }); } } },
    async postAnn(){ let v=document.getElementById('a-in').value.trim(); if(v||state.file){ await addDoc(collection(db,"announcements"),{text:v,img:state.file,file:state.file,time:Date.now()}); state.file=null; this.open('ann'); } }
};

// File input listeners
document.getElementById('avatar-input').addEventListener('change',e=>{ if(e.target.files[0]) app.compressImage(e.target.files[0],async(base64)=>{ await setDoc(doc(db,"profiles",state.user),{img:base64}); app.popup("Profile pic updated!"); }); });
document.getElementById('hw-file-input').addEventListener('change',async(e)=>{ state.hwFilesTemp=[]; app.popup("Processing..."); for(let f of e.target.files){ await new Promise(res=>{ app.compressImage(f,(base64)=>{ state.hwFilesTemp.push(base64); res(); }); }); } app.popup(`${state.hwFilesTemp.length} files ready`); app.renderHomework(); });
document.getElementById('report-file-input').addEventListener('change',async(e)=>{ if(e.target.files[0]) app.compressImage(e.target.files[0],(base64)=>{ state.reportFile=base64; app.showToast("Image attached","fa-exclamation"); }); });
onMessage(messaging,(payload)=>{ app.showToast(`${payload.notification?.title}: ${payload.notification?.body}`,'fa-bell'); });
setInterval(()=>{ let el=document.getElementById('clock'); if(el) el.innerText=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}); },1000);
